func (s MapStruct) JSONSize() int {
	size := 46
	size += len(s.Addresses) * 4
	for k, v := range s.Addresses {
		size += len(k) * 2
		size += v.JSONSize()
	}
	size += len(s.Counts) * 24
	for k := range s.Counts {
		size += len(k) * 2
	}
	size += len(s.Labels) * 4
	for k, v := range s.Labels {
		size += len(k) * 2
		size += len(v)*2 + 2
	}
	return size
}

func (s MapStruct) AppendJSON(dst []byte) ([]byte, error) {
	var err error
	_ = err
	dst = append(dst, "{\"addresses\":"...)
	if s.Addresses == nil {
		dst = append(dst, "null"...)
	} else {
		dst = append(dst, '{')
		firstAddresses := true
		for k, v := range s.Addresses {
			if firstAddresses {
				firstAddresses = false
				dst = append(dst, '"')
			} else {
				dst = append(dst, ",\""...)
			}
			dst = encode.AppendStringNoHTML(dst, k)
			dst = append(dst, ':')
			if dst, err = v.AppendJSON(dst); err != nil {
				return dst, err
			}
		}
		dst = append(dst, '}')
	}
	dst = append(dst, ",\"counts\":"...)
	if s.Counts == nil {
		dst = append(dst, "null"...)
	} else {
		dst = append(dst, '{')
		firstCounts := true
		for k, v := range s.Counts {
			if firstCounts {
				firstCounts = false
				dst = append(dst, '"')
			} else {
				dst = append(dst, ",\""...)
			}
			dst = encode.AppendStringNoHTML(dst, k)
			dst = append(dst, ':')
			dst = strconv.AppendInt(dst, int64(v), 10)
		}
		dst = append(dst, '}')
	}
	dst = append(dst, ",\"labels\":"...)
	if s.Labels == nil {
		dst = append(dst, "null"...)
	} else {
		dst = append(dst, '{')
		firstLabels := true
		for k, v := range s.Labels {
			if firstLabels {
				firstLabels = false
				dst = append(dst, '"')
			} else {
				dst = append(dst, ",\""...)
			}
			dst = encode.AppendStringNoHTML(dst, k)
			dst = append(dst, ":\""...)
			dst = encode.AppendStringNoHTML(dst, v)
		}
		dst = append(dst, '}')
	}
	return append(dst, '}'), nil
}

